export const TRICK_KEY = "black_bear";
export const TRICKS = ["bipedrise", "clawscar", "berrypluck", "denscrape", "bluffhuff", "mastforage", "ursus"] as const;
export const HAPPY = ["denscoal", "inkcoal", "densberry"] as const;
export type BlackBearTrickKind = (typeof TRICKS)[number];
export type BlackBearHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type BlackBearTrick = {
  kind: BlackBearTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type BlackBearHappy = {
  kind: BlackBearHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { denscoal: 1.70, inkcoal: 1.84, densberry: 1.76 } as const;
export const URSUS_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  ursus: URSUS_HOLD + RELEASE_S,
  bipedrise: 2.48,
  clawscar: 2.42,
  berrypluck: 2.56,
  denscrape: 2.44,
  bluffhuff: 2.40,
  mastforage: 2.38,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: BlackBearTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "ursus") return 40 + roll * 26;
  if (kind === "bluffhuff" || kind === "mastforage" || kind === "bipedrise") return 12.8 + roll * 9.4;
  if (kind === "clawscar" || kind === "berrypluck" || kind === "denscrape") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

export function pickTrick(rand?: number, musicOn?: boolean, lastKind?: BlackBearTrickKind | string | null) {
  if (musicOn) return "ursus" as const;
  const roll = rand == null ? Math.random() : rand;
  if (lastKind === "ursus") {
    if (roll < 0.17) return "bipedrise" as const;
    if (roll < 0.33) return "clawscar" as const;
    if (roll < 0.49) return "berrypluck" as const;
    if (roll < 0.65) return "denscrape" as const;
    if (roll < 0.83) return "bluffhuff" as const;
    return "mastforage" as const;
  }
  if (lastKind === "bipedrise") {
    if (roll < 0.16) return "ursus" as const;
    if (roll < 0.32) return "clawscar" as const;
    if (roll < 0.48) return "berrypluck" as const;
    if (roll < 0.64) return "denscrape" as const;
    if (roll < 0.82) return "bluffhuff" as const;
    return "mastforage" as const;
  }
  if (lastKind === "clawscar") {
    if (roll < 0.14) return "ursus" as const;
    if (roll < 0.3) return "bipedrise" as const;
    if (roll < 0.46) return "berrypluck" as const;
    if (roll < 0.62) return "denscrape" as const;
    if (roll < 0.8) return "bluffhuff" as const;
    return "mastforage" as const;
  }
  if (lastKind === "bluffhuff" || lastKind === "mastforage") {
    if (roll < 0.14) return "ursus" as const;
    if (roll < 0.3) return "bipedrise" as const;
    if (roll < 0.46) return "clawscar" as const;
    if (roll < 0.62) return "berrypluck" as const;
    if (roll < 0.78) return "denscrape" as const;
    return lastKind === "bluffhuff" ? ("mastforage" as const) : ("bluffhuff" as const);
  }
  if (roll < 0.14) return "ursus" as const;
  if (roll < 0.28) return "bipedrise" as const;
  if (roll < 0.42) return "clawscar" as const;
  if (roll < 0.56) return "berrypluck" as const;
  if (roll < 0.7) return "denscrape" as const;
  if (roll < 0.85) return "bluffhuff" as const;
  return "mastforage" as const;
}

export function happyCanStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function happyShouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function wantsThankYou(key: string | undefined | null) {
  return key === TRICK_KEY || key === "coal";
}

export function startThankYou(
  key: string | undefined | null,
  lastKind: BlackBearHappyKind | string | null | undefined,
  x: number,
  facing: 1 | -1,
  flags?: TrickFlags,
) {
  if (!wantsThankYou(key)) return null;
  if (!happyCanStart(flags || { cmd: "idle" })) return null;
  const pick = pickHappy(lastKind as BlackBearHappyKind | null | undefined);
  return { happy: beginHappy(pick, x, facing), kind: pick };
}

export function pickHappy(lastKind?: BlackBearHappyKind | null, rand?: number) {
  const pool = HAPPY.filter((k) => k !== lastKind);
  const list = pool.length ? pool : [...HAPPY];
  const roll = rand == null ? Math.random() : rand;
  return list[Math.floor(roll * list.length)] || list[0];
}

export function beginHappy(kind: BlackBearHappyKind | string, x: number, facing: 1 | -1): BlackBearHappy {
  const name = (HAPPY as readonly string[]).indexOf(kind) >= 0 ? (kind as BlackBearHappyKind) : "denscoal";
  return {
    kind: name,
    happy: true,
    phase: "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: name === "denscoal" ? "sit" : name === "inkcoal" ? "play" : "sit",
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

export function denscoalPose(t: number) {
  const u = Math.max(0, Math.min(1, t / HAPPY_DUR.denscoal));
  if (u < 0.14) {
    const s = u / 0.14;
    return { lift: s * 2.8, rot: s * 12, dx: 0, anim: "sit" as TrickAnim };
  }
  if (u < 0.78) {
    const flash = Math.sin(t * 2.2);
    return {
      lift: 2.8 + Math.abs(flash) * 1.4,
      rot: 12 + flash * 8,
      dx: flash * 0.08,
      anim: "sit" as TrickAnim,
    };
  }
  const s = (u - 0.78) / 0.22;
  return { lift: 2.0 * (1 - s), rot: 6 * (1 - s), dx: 0, anim: "idle" as TrickAnim };
}

export function inkcoalPose(t: number) {
  const u = Math.max(0, Math.min(1, t / HAPPY_DUR.inkcoal));
  if (u < 0.12) {
    const s = u / 0.12;
    return { lift: s * 3.7, rot: s * -14, dx: s * 0.15, anim: "play" as TrickAnim };
  }
  if (u < 0.8) {
    const wriggle = Math.sin(t * 2.6);
    return {
      lift: 3.4 + Math.abs(wriggle) * 1.6,
      rot: -14 + wriggle * 10,
      dx: wriggle * 0.12,
      anim: "play" as TrickAnim,
    };
  }
  const s = (u - 0.8) / 0.2;
  return { lift: 2.2 * (1 - s), rot: -6 * (1 - s), dx: 0, anim: "sit" as TrickAnim };
}

export function densberryPose(t: number) {
  return {
    lift: 2.2 + Math.abs(Math.sin(t * 0.58)) * 1.1,
    rot: Math.sin(t * 0.58) * 8,
    dx: Math.sin(t * 0.4) * 0.06,
    anim: "sit" as TrickAnim,
  };
}

export function stepHappy(happy: BlackBearHappy | null | undefined, dt: number, flags?: TrickFlags) {
  if (!happy || happy.phase === "done") return happy;
  if (happyShouldAbort(flags)) {
    return { ...happy, phase: "done" as const, t: 0, lift: 0, rot: 0, anim: "idle" as TrickAnim, abort: true };
  }
  const next = { ...happy, t: happy.t + Math.max(0, dt) };
  const hold = HAPPY_DUR[next.kind];
  if (next.kind === "denscoal") {
    const pose = denscoalPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "inkcoal") {
    const pose = inkcoalPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else {
    const pose = densberryPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  }
  if (next.t >= hold) return { ...next, phase: "done" as const, lift: 0, rot: 0, anim: "idle" as TrickAnim };
  return next;
}

export function sleepHoldFrame(_key?: string | null, _frameCount?: number) {
  return null;
}

export function beginTrick(kind: BlackBearTrickKind, x: number, facing: 1 | -1): BlackBearTrick {
  const anim: TrickAnim =
    kind === "ursus"
      ? "sit"
      : kind === "bipedrise"
        ? "talk"
        : kind === "clawscar"
          ? "play"
          : kind === "berrypluck"
            ? "play"
            : kind === "denscrape"
              ? "talk"
              : kind === "bluffhuff"
                ? "talk"
                : kind === "mastforage"
                  ? "play"
                  : "sit";
  return {
    kind,
    phase: kind === "ursus" ? "hold" : "go",
    t: 0,
    x,
    lift: 0,
    rot: 0,
    anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}

export function ursusPose(t: number) {
  return {
    lift: 2.4 + Math.abs(Math.sin(t * 0.42)) * 1.2,
    rot: -0.18 + Math.sin(t * 0.36) * 0.35,
  };
}

export function releasePose(t: number) {
  const u = Math.max(0, Math.min(1, t / RELEASE_S));
  return { lift: 2.4 * (1 - Math.sin(u * Math.PI * 0.5)), rot: -0.18 * (1 - u) };
}

export function bipedrisePose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.bipedrise));
  const face = facing == null ? 1 : facing;
  if (u < 0.14) {
    const s = smoothstep(u / 0.14);
    return { x: fromX + face * s * 0.8, lift: s * 3.5, rot: s * 16 * face, anim: "talk" as TrickAnim };
  }
  if (u < 0.78) {
    const tip = Math.sin(t * 2.4);
    return {
      x: fromX + face * (0.8 + tip * 0.12),
      lift: 3.5 + Math.abs(tip) * 1.5,
      rot: face * (16 + tip * 10),
      anim: "talk" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX + face * 0.8 * (1 - s),
    lift: 1.4 * (1 - s),
    rot: face * (4 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function clawscarPose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.clawscar));
  const face = facing == null ? 1 : facing;
  if (u < 0.12) {
    const s = smoothstep(u / 0.12);
    return { x: fromX, lift: s * 2.6, rot: s * -10 * face, anim: "play" as TrickAnim };
  }
  if (u < 0.78) {
    const bob = Math.sin(t * 2.8);
    return {
      x: fromX + face * bob * 0.5,
      lift: 2.6 + Math.abs(bob) * 1.4,
      rot: face * (-10 + bob * 12),
      anim: "play" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX,
    lift: 1.2 * (1 - s),
    rot: face * (-3 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function berrypluckPose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.berrypluck));
  const face = facing == null ? 1 : facing;
  if (u < 0.14) {
    const s = smoothstep(u / 0.14);
    return { x: fromX, lift: s * 3.8, rot: s * 14 * face, anim: "play" as TrickAnim };
  }
  if (u < 0.78) {
    const cast = Math.sin(t * 2.6);
    return {
      x: fromX - face * cast * 0.16,
      lift: 3.6 + Math.abs(cast) * 1.6,
      rot: face * (14 + cast * 12),
      anim: "play" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX,
    lift: 1.4 * (1 - s),
    rot: face * (4 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

